package policy; import java.util.Map;import java.util.TreeMap; public final class PolicySummary{public String summarize(PolicyDocument doc){Map<String,Integer>actions=new TreeMap<>();Map<String,Integer>chains=new TreeMap<>();if(doc!=null)for(FirewallRule r:doc.rules()){actions.merge(r.action(),1,Integer::sum);chains.merge(r.chain(),1,Integer::sum);}RuleOrderingAnalyzer a=new RuleOrderingAnalyzer();return"rules="+(doc==null?0:doc.size())+" actions="+actions+" chains="+chains+" duplicates="+(doc==null?0:a.duplicates(doc).size())+" shadowed="+(doc==null?0:a.shadowed(doc).size());}}
